  return !lt(y, x);
};

var model = function() {
  var a = (randomInteger(201) - 100 + 32768) % 32768;
  var b = (randomInteger(201) - 100 + 32768) % 32768;
  var c = (randomInteger(201) - 100 + 32768) % 32768;
